INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist FF02::1 die einzige Multicast-Gruppe?', 2, '[{"text": "Nein", "correct": true, "because": "Es gibt viele Gruppen"}, {"text": "Ja", "correct": false, "because": "Nur eine von vielen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte erreicht FF02::1?', 3, '[{"text": "Alle Knoten im Segment", "correct": true, "because": "Link-lokal alle"}, {"text": "Nur Router", "correct": false, "because": "Das ist FF02::2"}, {"text": "Globale Knoten", "correct": false, "because": "Nur link-lokal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Multicast-Gruppen sind typisch?', 5, '[{"text": "FF02::1", "correct": true, "because": "Alle Knoten"}, {"text": "FF02::2", "correct": true, "because": "Alle Router"}, {"text": "FE80::1", "correct": false, "because": "Unicast"}, {"text": "2001:db8::1", "correct": false, "because": "Globale Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FF02::1 ist link-lokal. b) Es erreicht nur Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Knoten, nicht nur Server"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Multicast-Gruppen?', 4, '[{"text": "Gruppenadresse", "correct": false, "because": "Definiert Empfänger"}, {"text": "Scope", "correct": false, "because": "Begrenzt Reichweite"}, {"text": "Einzel-IPs", "correct": true, "because": "Gruppenfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob FF02::2 alle Geräte anspricht?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Router"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit FF02::1"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gruppe wähle ich für alle Router?', 3, '[{"text": "FF02::2", "correct": true, "because": "Router im Segment"}, {"text": "FF02::1", "correct": false, "because": "Alle Knoten"}, {"text": "FF05::1", "correct": false, "because": "Site-lokal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben Multicast-Gruppen?', 5, '[{"text": "Spezifische Adressen", "correct": true, "because": "z. B. FF02::1"}, {"text": "Link-lokale Reichweite", "correct": true, "because": "Scope 2"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}, {"text": "Hohe Latenz", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) FF02::1 erreicht alle Knoten. b) Es ist global gültig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Link-lokal, nicht global"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Multicast-Gruppen?', 4, '[{"text": "Gruppen-ID", "correct": false, "because": "Definiert Empfänger"}, {"text": "Scope-Wert", "correct": false, "because": "Begrenzt Reichweite"}, {"text": "Portnummern", "correct": true, "because": "Transportebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist FF02::1 für Router gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Knoten, nicht nur Router"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit FF02::2"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse nutze ich für eine spezifische Gerätegruppe?', 4, '[{"text": "FF02::1:FFXX:XXXX", "correct": true, "because": "Solicited-Node"}, {"text": "FF02::1", "correct": false, "because": "Alle Knoten"}, {"text": "FE80::1", "correct": false, "because": "Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multicast-Gruppen nur lokal sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Scope kann variieren"}, {"text": "Ja", "correct": false, "because": "Nicht auf link-lokal beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Multicast-Gruppen?', 3, '[{"text": "Korrekte Adresse", "correct": true, "because": "Erreicht Zielgruppe"}, {"text": "Schnelle Antwort", "correct": false, "because": "Diagnoseabhängig"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FF02::2 ist für Router. b) FF02::1 ist site-lokal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "FF02::1 ist link-lokal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Multicast-Gruppen?', 5, '[{"text": "Effiziente Kommunikation", "correct": true, "because": "Gruppenabfrage"}, {"text": "Zielgerichtete Ansprache", "correct": true, "because": "Spezifische Gruppen"}, {"text": "Datenkompression", "correct": false, "because": "Nicht enthalten"}, {"text": "Geringe Latenz", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Multicast-Gruppen unwichtig?', 3, '[{"text": "Gruppenadresse", "correct": false, "because": "Definiert Empfänger"}, {"text": "Scope", "correct": false, "because": "Begrenzt Reichweite"}, {"text": "Einzel-MAC", "correct": true, "because": "Gruppenfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erreicht FF02::1 auch globale Geräte?', 3, '[{"text": "Nein", "correct": true, "because": "Nur link-lokal"}, {"text": "Ja", "correct": false, "because": "Scope-beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob FF02::1 dynamisch ist?', 2, '[{"text": "Nein", "correct": true, "because": "Feste Adresse"}, {"text": "Ja", "correct": false, "because": "Statisch definiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gruppe wähle ich für alle DHCPv6-Server?', 4, '[{"text": "FF02::1:2", "correct": true, "because": "DHCPv6-Server link-lokal"}, {"text": "FF02::1", "correct": false, "because": "Alle Knoten"}, {"text": "FF05::1", "correct": false, "because": "Site-lokal"}]');
